-- The relatório analítico uses rateioMem which maps equipment to subsetores via SETOR_PARA_SUBSETOR_MEM
-- Let's check what codigoTag the equipamentos have that are assigned to setorId 9 (DESMONTE PRIMÁRIO) or 10 (DESMONTE SECUNDÁRIO)
SELECT id, codigoTag, nomeDoEquipamento, setorId FROM equipamentos WHERE setorId IN (9, 10, 7) ORDER BY setorId, codigoTag LIMIT 30;
